<http://example.org/onto/assessment> a owl:Ontology ;
    rdfs:comment "An OWL ontology of educational assessment, derived strictly from a corpus describing assessment types, validity, reliability, scoring, and related testing concepts. Where the corpus presents conflicting classification claims (e.g. coordinate lists vs. subsumption statements for the same pair of concepts), both axioms are encoded and the tension is documented in rdfs:comment, per modeling instructions. Several axioms that produced logical unsatisfiability (e.g. erroneous rdfs:subClassOf statements conflicting with disjoint partitions) have been removed or weakened to restore satisfiability, per repair instructions." .

ea:AchievementTest a owl:Class ;
    rdfs:comment "'Backward-looking': measures knowledge/skills already learned." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest [ a owl:Restriction ;
                        owl:onProperty ea:hasTestFunction ;
                        owl:someValuesFrom ea:AchievementFunction ] ) ] .

ea:AllDisjointErrors a owl:AllDisjointClasses ;
    owl:members ( ea:RandomError ea:SystematicError ) .

ea:AllDisjointGradingApproaches a owl:AllDisjointClasses ;
    owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:AllDisjointMCFamilies a owl:AllDisjointClasses ;
